Change(genesis='66602cd0dec37d58d03eec9518ca805a7ac38ea912d2b0c366a0b67b4b9f50b6', deps=(), event=Decided(decision='frameworklanguages', at=datetime(2026, 11, 2, 0, 0, 0), actor='owner', title='Pages are Rust programs over a view tree; Typst draws content; TypeScript only paints', body="A page's model, update and view are Rust (app/pages, over app/viewtree), compiled to one wasm module. Content (todos, cards, documents) is drawn by Typst. The TypeScript in web/src is a generic painter and host: it applies view trees to the DOM, runs effects and holds no page logic. No language is embedded in another. A page is judged by its user-visible character, not by its code.", rationale="The owner, 2026-11-02, choosing among Rust, Typst and TypeScript: one language per job, borrowing Lustre's and Unison's ideas without adopting either.", supersedes=('webphone',)))